if (element.querySelector('.sort-dropdown-container')) return;

var container = document.createElement('div');
container.className = 'sort-dropdown-container';
container.setAttribute('data-sort-dropdown', 'true');
container.style.cssText = 'position: relative; display: inline-block; vertical-align: middle; margin-left: 4px;';

var dropdownButton = document.createElement('button');
dropdownButton.type = 'button';
dropdownButton.style.cssText = 'display: flex; align-items: center; gap: 6px; padding: 8px 16px; border-radius: 24px; border: 1px solid #ccc; background: #fff; font-size: 14px; font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif; cursor: pointer; white-space: nowrap; height: 40px; box-sizing: border-box; transition: background 0.2s, border-color 0.2s;';
dropdownButton.setAttribute('aria-haspopup', 'listbox');
dropdownButton.setAttribute('aria-expanded', 'false');
dropdownButton.setAttribute('aria-label', 'Sort by');

var labelSpan = document.createElement('span');
labelSpan.style.cssText = 'color: #555; font-weight: 500;';
labelSpan.textContent = 'Sort by:';

var selectedSpan = document.createElement('span');
selectedSpan.id = 'sort-selected-value';
selectedSpan.style.cssText = 'color: #111; font-weight: 600;';
selectedSpan.textContent = 'Relevance';

var chevronSvg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
chevronSvg.setAttribute('width', '12');
chevronSvg.setAttribute('height', '12');
chevronSvg.setAttribute('viewBox', '0 0 12 12');
chevronSvg.setAttribute('fill', 'none');
chevronSvg.style.cssText = 'transition: transform 0.2s; flex-shrink: 0;';
chevronSvg.innerHTML = '<path d="M3 4.5L6 7.5L9 4.5" stroke="#555" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/>';

dropdownButton.appendChild(labelSpan);
dropdownButton.appendChild(selectedSpan);
dropdownButton.appendChild(chevronSvg);

var menu = document.createElement('div');
menu.setAttribute('role', 'listbox');
menu.setAttribute('aria-label', 'Sort options');
menu.style.cssText = 'position: absolute; top: calc(100% + 6px); left: 0; min-width: 180px; background: #fff; border-radius: 12px; box-shadow: 0 4px 24px rgba(0,0,0,0.15), 0 1px 4px rgba(0,0,0,0.1); padding: 6px 0; z-index: 9999; display: none; border: 1px solid #e8e8e8;';

var options = [
  { value: 'Relevance', icon: '★' },
  { value: 'Newest', icon: '🕐' },
  { value: 'Most Saved', icon: '💾' }
];

options.forEach(function(opt) {
  var item = document.createElement('div');
  item.setAttribute('role', 'option');
  item.setAttribute('data-sort-value', opt.value);
  item.style.cssText = 'padding: 10px 16px; cursor: pointer; font-size: 14px; font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif; display: flex; align-items: center; gap: 10px; transition: background 0.15s;';

  var iconSpan = document.createElement('span');
  iconSpan.style.cssText = 'font-size: 16px; width: 20px; text-align: center;';
  iconSpan.textContent = opt.icon;

  var textSpan = document.createElement('span');
  textSpan.style.cssText = 'color: #333; font-weight: 500;';
  textSpan.textContent = opt.value;

  item.appendChild(iconSpan);
  item.appendChild(textSpan);

  if (opt.value === 'Relevance') {
    var checkMark = document.createElement('span');
    checkMark.style.cssText = 'margin-left: auto; color: #e60023; font-weight: bold; font-size: 16px;';
    checkMark.textContent = '✓';
    item.appendChild(checkMark);
  }

  item.addEventListener('mouseenter', function() {
    item.style.background = '#f5f5f5';
  });
  item.addEventListener('mouseleave', function() {
    if (item.getAttribute('data-sort-value') !== selectedSpan.textContent) {
      item.style.background = 'transparent';
    }
  });

  item.addEventListener('click', function() {
    var chosen = item.getAttribute('data-sort-value');
    selectedSpan.textContent = chosen;
    menu.style.display = 'none';
    dropdownButton.setAttribute('aria-expanded', 'false');
    chevronSvg.style.transform = 'rotate(0deg)';

    // Update checkmarks
    var allItems = menu.querySelectorAll('[role="option"]');
    allItems.forEach(function(ai) {
      var existingCheck = ai.querySelector('.sort-checkmark');
      if (existingCheck) existingCheck.remove();
    });

    var checkMark = document.createElement('span');
    checkMark.className = 'sort-checkmark';
    checkMark.style.cssText = 'margin-left: auto; color: #e60023; font-weight: bold; font-size: 16px;';
    checkMark.textContent = '✓';
    item.appendChild(checkMark);
  });

  menu.appendChild(item);
});

dropdownButton.addEventListener('click', function(e) {
  e.stopPropagation();
  var isOpen = menu.style.display === 'block';
  menu.style.display = isOpen ? 'none' : 'block';
  dropdownButton.setAttribute('aria-expanded', (!isOpen).toString());
  chevronSvg.style.transform = isOpen ? 'rotate(0deg)' : 'rotate(180deg)';
});

dropdownButton.addEventListener('mouseenter', function() {
  dropdownButton.style.background = '#f5f5f5';
  dropdownButton.style.borderColor = '#aaa';
});
dropdownButton.addEventListener('mouseleave', function() {
  dropdownButton.style.background = '#fff';
  dropdownButton.style.borderColor = '#ccc';
});

container.appendChild(dropdownButton);
container.appendChild(menu);

// Insert after the filter button's parent wrapper
var parentModule = element;
if (parentModule && parentModule.parentNode) {
  var siblingWrapper = parentModule.parentNode;
  if (siblingWrapper && siblingWrapper.parentNode) {
    siblingWrapper.parentNode.insertBefore(container, siblingWrapper.nextSibling);
  }
}

document.addEventListener('click', function closeMenu(e) {
  if (!container.contains(e.target)) {
    menu.style.display = 'none';
    dropdownButton.setAttribute('aria-expanded', 'false');
    chevronSvg.style.transform = 'rotate(0deg)';
  }
});
